const workflows = ($json.data || []);

// Workflows que devem SEMPRE estar ativos
const EXPECTED_ACTIVE = [
  'Zabbix — Remediação de Serviços Windows',
  'Zabbix — Disco Cheio e Host Indisponível',
  'Zabbix — Alerta de CPU e Memória',
  'Zabbix — Relatório de Hosts Fantasmas',
  'Zabbix — Relatório Diário de Remediações'
];

const inactive = [];
const missing  = [];
const allNames = workflows.map(w => w.name);

for (const expected of EXPECTED_ACTIVE) {
  const wf = workflows.find(w => w.name === expected);
  if (!wf) {
    missing.push(expected);
  } else if (!wf.active) {
    inactive.push({ name: wf.name, updatedAt: wf.updatedAt });
  }
}

const hasProblems = inactive.length > 0 || missing.length > 0;

return [{ json: { inactive, missing, hasProblems, total: workflows.length, active: workflows.filter(w => w.active).length } }];

const { inactive, missing, total, active } = $json;
const now = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const facts = [];

for (const wf of inactive) {
  facts.push({
    name: wf.name,
    value: 'INATIVO — ultima modificacao: ' + new Date(wf.updatedAt).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })
  });
}

for (const name of missing) {
  facts.push({ name, value: 'NAO ENCONTRADO no n8n' });
}

return [{ json: { teams_body: JSON.stringify({
  '@type': 'MessageCard',
  '@context': 'http://schema.org/extensions',
  themeColor: 'FF0000',
  summary: 'ALERTA: ' + (inactive.length + missing.length) + ' workflow(s) com problema',
  sections: [{
    activityTitle: 'Health Check — Workflows com Problema',
    activitySubtitle: now + ' | ' + active + '/' + total + ' workflows ativos',
    facts,
    markdown: true
  }]
}) } }];
